fn tri(n: usize, m: usize, k: i32) -> Vec<Vec<f64>> {
    let mut matrix = Vec::with_capacity(n);
    for i in 0..n {
        let mut row = Vec::with_capacity(m);
        for j in 0..m {
            // Convert i and j to i32 for comparison with k
            let j_i32 = j as i32;
            let i_i32 = i as i32;
            if j_i32 <= i_i32 + k {
                row.push(1.0);
            } else {
                row.push(0.0);
            }
        }
        matrix.push(row);
    }
    matrix
}